function sensorRing(capacity, operations) {
  const kept = [];
  const results = [];
  for (const operation of operations) {
    const name = operation[0];
    if (name === "write") {
      kept.push(operation[1]);
      if (kept.length > capacity) kept.shift();
    } else if (name === "read") {
      results.push(kept.length > 0 ? kept.shift() : null);
    } else if (name === "newest") {
      results.push(kept.length > 0 ? kept[kept.length - 1] : null);
    } else {
      results.push(kept.length);
    }
  }
  return results;
}

function sensorRing(capacity, operations) {
  const slots = new Array(capacity).fill(0);
  let head = 0;
  let count = 0;
  const results = [];
  for (const operation of operations) {
    const name = operation[0];
    if (name === "write") {
      if (count === capacity) {
        slots[head] = operation[1];
        head = (head + 1) % capacity;
      } else {
        slots[(head + count) % capacity] = operation[1];
        count++;
      }
    } else if (name === "read") {
      if (count === 0) {
        results.push(null);
      } else {
        results.push(slots[head]);
        head = (head + 1) % capacity;
        count--;
      }
    } else if (name === "newest") {
      results.push(count === 0 ? null : slots[(head + count - 1) % capacity]);
    } else {
      results.push(count);
    }
  }
  return results;
}
